import * as THREE from './three.module.js';
export function architecturalGlass(opacity=.48){let map=null;if(typeof document!=='undefined'){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=256;const c=canvas.getContext('2d'),g=c.createLinearGradient(0,0,0,256);g.addColorStop(0,'#587482');g.addColorStop(.58,'#a9bcb9');g.addColorStop(1,'#607b72');c.fillStyle=g;c.fillRect(0,0,128,256);c.fillStyle='#d6e9df18';c.beginPath();c.moveTo(0,0);c.lineTo(23,0);c.lineTo(128,190);c.lineTo(128,238);c.closePath();c.fill();map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;}const glass=new THREE.MeshPhysicalMaterial({color:'#afcbd0',map,roughness:.18,metalness:0,transmission:.25,thickness:.035,transparent:true,opacity,depthWrite:false,side:THREE.DoubleSide});glass.userData.architecturalGlass=true;return glass;}
